/* @lc app=leetcode id=2096 lang=kotlin */ class Solution { fun getDirections(root: TreeNode?, startValue: Int, destValue: Int): String = HashMap<TreeNode, Pair<TreeNode, Char>>().let { par -> generateSequence(listOf(root!!)) { f -> f.flatMap { n -> listOfNotNull(n.left?.also { par[it] = n to 'L' }, n.right?.also { par[it] = n to 'R' }) }.takeIf { it.isNotEmpty() } }.flatten().toList().let { all -> all.first { it.`val` == startValue }.let { s -> all.first { it.`val` == destValue }.let { d -> generateSequence(s) { par[it]?.first }.mapNotNull { par[it]?.second }.toList().reversed().let { ps -> generateSequence(d) { par[it]?.first }.mapNotNull { par[it]?.second }.toList().reversed().let { pd -> ps.zip(pd).takeWhile { (a, b) -> a == b }.size.let { c -> "U".repeat(ps.size - c) + pd.drop(c).joinToString("") } } } } } } } }